public class ClientApp : Form {
 WebView2 browser; bool exiting; NotifyIcon tray;
 [STAThread] public static void Main(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool first;using(var mutex=new System.Threading.Mutex(true,"Local\\APTechClient-"+Environment.UserName,out first)){if(!first){MessageBox.Show("AP Tech Client is already open. Use its taskbar or tray icon.");return;}Application.Run(new ClientApp());mutex.ReleaseMutex();}}
 ClientApp(){Text="AP Tech Client 1.0.0";ClientSize=new Size(1100,780);MinimumSize=new Size(700,540);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath)??SystemIcons.Application;BackColor=Color.FromArgb(15,25,22);tray=new NotifyIcon{Icon=Icon,Visible=true,Text="AP Tech Client"};var menu=new ContextMenuStrip();menu.Items.Add("Open",null,(s,e)=>Open());menu.Items.Add("Exit",null,(s,e)=>{exiting=true;Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>Open();FormClosing+=(s,e)=>{if(!exiting&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Hide();return;}tray.Dispose();if(browser!=null)browser.Dispose();};Shown+=async(s,e)=>{try{browser=new WebView2{Dock=DockStyle.Fill};Controls.Add(browser);var profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"APTechClient","WebView2");var env=await CoreWebView2Environment.CreateAsync(null,profile);await browser.EnsureCoreWebView2Async(env);browser.CoreWebView2.Settings.IsPasswordAutosaveEnabled=false;browser.CoreWebView2.Settings.AreDevToolsEnabled=false;browser.CoreWebView2.PermissionRequested+=(sender,args)=>{args.State=CoreWebView2PermissionState.Deny;};browser.CoreWebView2.NavigationStarting+=(sender,args)=>{Uri uri;if(!Uri.TryCreate(args.Uri,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="www.aptechagency.com"||uri.Port!=443)args.Cancel=true;};browser.CoreWebView2.NewWindowRequested+=(sender,args)=>{args.Handled=true;Uri uri;if(args.IsUserInitiated&&Uri.TryCreate(args.Uri,UriKind.Absolute,out uri)&&uri.Scheme=="https")Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});};browser.CoreWebView2.Navigate("https://www.aptechagency.com/hub-app?surface=client");}catch(Exception){if(browser!=null){browser.Dispose();Controls.Remove(browser);}var help=new LinkLabel{Dock=DockStyle.Fill,Text="AP Tech Client needs Microsoft Edge WebView2 Runtime. Click to open Microsoft's official download page.",Padding=new Padding(30),LinkColor=Color.LightGreen};help.LinkClicked+=(sender,args)=>Process.Start(new ProcessStartInfo("https://developer.microsoft.com/microsoft-edge/webview2/"){UseShellExecute=true});Controls.Add(help);}};}
 void Open(){Show();WindowState=FormWindowState.Normal;Activate();}
